package com.example.erp.service;
import com.example.erp.model.Models.*;import com.example.erp.repo.InventoryRepo;import com.example.erp.repo.TransferRepo;import com.example.erp.repo.OrderRepo;import com.example.erp.repo.WorkRepo;import jakarta.transaction.Transactional;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class ErpService{
final InventoryRepo inv;final TransferRepo tr;final OrderRepo ord;final WorkRepo wo;public ErpService(InventoryRepo i,TransferRepo t,OrderRepo o,WorkRepo w){inv=i;tr=t;ord=o;wo=w;}
@Transactional public CustomerOrder reserve(String item,String loc,String batch,String customer,int qty){if(qty<=0)throw bad("Quantity must be positive");Inventory x=inv.lock(item,loc,batch).orElseThrow(()->bad("Inventory not found"));if(x.available()<qty)throw bad("Insufficient available inventory");x.reservedQuantity+=qty;inv.save(x);CustomerOrder o=new CustomerOrder();o.item=item;o.location=loc;o.customer=customer;o.quantity=qty;o.status="RESERVED";return ord.save(o);}
@Transactional public Transfer dispatch(Long id){Transfer t=tr.findById(id).orElseThrow(()->bad("Transfer not found"));if(!"REQUESTED".equals(t.status))throw bad("Transfer is not in REQUESTED state");Inventory x=inv.lock(t.item,t.sourceLocation,"B1").orElseThrow(()->bad("Source inventory not found"));if(x.available()<t.quantity)throw bad("Insufficient source inventory");x.physicalQuantity-=t.quantity;inv.save(x);t.status="DISPATCHED";return tr.save(t);}
@Transactional public Transfer receive(Long id){Transfer t=tr.findById(id).orElseThrow(()->bad("Transfer not found"));if("RECEIVED".equals(t.status)||t.received)throw bad("Transfer already received");if(!"DISPATCHED".equals(t.status))throw bad("Only dispatched transfers can be received");Inventory x=inv.lock(t.item,t.destinationLocation,"B1").orElseGet(()->{Inventory n=new Inventory();n.item=t.item;n.location=t.destinationLocation;n.batch="B1";n.category="Transferred";return n;});x.physicalQuantity+=t.quantity;inv.save(x);t.status="RECEIVED";t.received=true;return tr.save(t);}
public Transfer createTransfer(Transfer t){if(t.quantity<=0)throw bad("Quantity must be positive");t.status="REQUESTED";t.received=false;return tr.save(t);}public WorkOrder saveWork(WorkOrder w){w.status=w.status==null?"ASSIGNED":w.status;return wo.save(w);}RuntimeException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}}
